#!/usr/bin/env node
// Generates src/plugins/registry.generated.ts from plugins.json — the build-time
// plugin registry. Core imports ONLY the generated file (never a plugin by name),
// so the bundle includes exactly the enabled plugins and both ship paths (the
// code-split hosted build and the inlined embed/desktop zip) carry the same set.
//
// Run: `node scripts/gen-plugin-registry.mjs` (also wired as an npm script).
// The generated file is committed so a plain `vite build` needs no pre-step.

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, "..");
const configPath = resolve(root, "plugins.json");
const outPath = resolve(root, "src/plugins/registry.generated.ts");

const config = JSON.parse(readFileSync(configPath, "utf8"));
const enabled = Array.isArray(config.enabled) ? config.enabled : [];

// Build-time overlay: extra plugin packages enabled without editing the committed
// plugins.json — a comma-separated ADA_PLUGINS_EXTRA (package names, or
// package=importName). This is how an externally-overlaid plugin (dropped into
// packages/plugins/ at build time) registers, keeping core config plugin-neutral.
const extraEnv = (process.env.ADA_PLUGINS_EXTRA || "")
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean)
  .map((spec) => {
    const [pkg, importName] = spec.split("=").map((s) => s.trim());
    return importName ? { package: pkg, importName } : pkg;
  });
if (extraEnv.length) {
  const seen = new Set(enabled.map((e) => (typeof e === "string" ? e : e.package)));
  for (const e of extraEnv) {
    const pkg = typeof e === "string" ? e : e.package;
    if (!seen.has(pkg)) {
      enabled.push(e);
      seen.add(pkg);
    }
  }
  console.log(`[gen-plugin-registry] +${extraEnv.length} from ADA_PLUGINS_EXTRA`);
}

const imports = [];
const calls = [];
enabled.forEach((entry, i) => {
  const pkg = typeof entry === "string" ? entry : entry.package;
  const importName = (typeof entry === "object" && entry.importName) || "register";
  if (!pkg) throw new Error(`plugins.json entry ${i} has no package`);
  const local = `register_${i}`;
  imports.push(`import { ${importName} as ${local} } from "${pkg}";`);
  calls.push(`  ${local}(); // ${pkg}`);
});

const banner =
  "// AUTO-GENERATED by scripts/gen-plugin-registry.mjs from plugins.json.\n" +
  "// DO NOT EDIT BY HAND — re-run the generator to change the enabled plugin set.\n" +
  "//\n" +
  "// Core imports ONLY this file to load plugins; it never names a plugin\n" +
  "// elsewhere. registerBuiltinPlugins() is invoked once at app bootstrap.\n";

const body =
  banner +
  "\n" +
  (imports.length ? imports.join("\n") + "\n\n" : "\n") +
  "export function registerBuiltinPlugins(): void {\n" +
  (calls.length ? calls.join("\n") + "\n" : "  /* no plugins enabled */\n") +
  "}\n";

writeFileSync(outPath, body);
console.log(`[gen-plugin-registry] wrote ${outPath} (${enabled.length} plugin(s))`);
